1	/**
2	 * Geradores de PDF para o módulo Funcionários (DP/RH).
3	 * - Aviso Prévio de Férias (CLT Art. 135)
4	 * - Advertência Disciplinar
5	 *
6	 * Layout consistente com o padrão Momma. Usa jspdf.
7	 */
8	
9	import { jsPDF } from 'jspdf';
10	
11	// =============================================================================
12	// AVISO PRÉVIO DE FÉRIAS
13	// =============================================================================
14	export interface AvisoFeriasInput {
15	  empresa: string;
16	  cnpj?: string | null;
17	  empregado: string;
18	  cpf: string;
19	  cargo: string;
20	  matricula?: string | null;
21	  ctps_numero?: string | null;
22	  ctps_serie?: string | null;
23	  periodo_aquisitivo_inicio: string; // YYYY-MM-DD
24	  periodo_aquisitivo_fim: string;
25	  data_inicio_gozo: string;
26	  data_fim_gozo: string;
27	  cidade?: string;
28	  data_emissao?: string; // ISO
29	}
30	
31	function formatDate(iso: string): string {
32	  return new Date(iso + (iso.includes('T') ? '' : 'T00:00:00')).toLocaleDateString('pt-BR');
33	}
34	
35	function formatCpf(cpf: string): string {
36	  const d = (cpf || '').replace(/\D/g, '');
37	  if (d.length !== 11) return cpf;
38	  return `${d.slice(0, 3)}.${d.slice(3, 6)}.${d.slice(6, 9)}-${d.slice(9)}`;
39	}
40	
41	function formatCnpj(cnpj: string): string {
42	  const d = (cnpj || '').replace(/\D/g, '');
43	  if (d.length !== 14) return cnpj;
44	  return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8, 12)}-${d.slice(12)}`;
45	}
46	
47	function dataExtenso(iso: string): string {
48	  const d = new Date(iso);
49	  const meses = [
50	    'janeiro','fevereiro','março','abril','maio','junho',
51	    'julho','agosto','setembro','outubro','novembro','dezembro',
52	  ];
53	  return `${d.getDate()}, ${meses[d.getMonth()]}, ${d.getFullYear()}`;
54	}
55	
56	export function gerarAvisoFeriasPdf(input: AvisoFeriasInput): jsPDF {
57	  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
58	  const w = doc.internal.pageSize.getWidth();
59	  const margin = 15;
60	  let y = 20;
61	
62	  // Title
63	  doc.setFont('helvetica', 'bold');
64	  doc.setFontSize(16);
65	  doc.text('AVISO PRÉVIO DE FÉRIAS', w / 2, y, { align: 'center' });
66	  y += 6;
67	  doc.setFontSize(10);
68	  doc.setFont('helvetica', 'normal');
69	  doc.text('Capítulo VI - Título II da CLT', w / 2, y, { align: 'center' });
70	  y += 8;
71	
72	  // Box: legal
73	  doc.setLineWidth(0.3);
74	  doc.rect(margin, y, w - margin * 2, 18);
75	  doc.setFontSize(8);
76	  doc.text(
77	    'Decr. Lei n.5452 de 01/05/1943, com as alterações do Dec. - Lei n. 1535 de 13/04/1977',
78	    w / 2,
79	    y + 6,
80	    { align: 'center' },
81	  );
82	  doc.text(
83	    'De acordo com o art. 135 da CLT, participando no mínimo com 30 dias de antecedência',
84	    w / 2,
85	    y + 12,
86	    { align: 'center' },
87	  );
88	  y += 22;
89	
90	  // Box: empresa/empregado
91	  doc.rect(margin, y, w - margin * 2, 32);
92	  doc.setFontSize(10);
93	  doc.setFont('helvetica', 'bold');
94	  doc.text('Empresa:', margin + 3, y + 6);
95	  doc.setFont('helvetica', 'normal');
96	  doc.text(input.empresa, margin + 30, y + 6);
97	
98	  doc.setFont('helvetica', 'bold');
99	  doc.text('Empregado:', margin + 3, y + 13);
100	  doc.setFont('helvetica', 'normal');
101	  doc.text(input.empregado, margin + 30, y + 13);
102	
103	  doc.setFont('helvetica', 'bold');
104	  doc.text('CPF:', margin + 3, y + 20);
105	  doc.setFont('helvetica', 'normal');
106	  doc.text(formatCpf(input.cpf), margin + 30, y + 20);
107	
108	  if (input.matricula) {
109	    doc.setFont('helvetica', 'bold');
110	    doc.text('Matrícula:', margin + 90, y + 20);
111	    doc.setFont('helvetica', 'normal');
112	    doc.text(input.matricula, margin + 115, y + 20);
113	  }
114	
115	  doc.setFont('helvetica', 'bold');
116	  doc.text('Função:', margin + 3, y + 27);
117	  doc.setFont('helvetica', 'normal');
118	  doc.text(input.cargo, margin + 30, y + 27);
119	
120	  if (input.ctps_numero || input.ctps_serie) {
121	    doc.setFont('helvetica', 'bold');
122	    doc.text('CTPS:', margin + 90, y + 27);
123	    doc.setFont('helvetica', 'normal');
124	    doc.text(`${input.ctps_numero ?? '-'} / ${input.ctps_serie ?? '-'}`, margin + 110, y + 27);
125	  }
126	
127	  y += 36;
128	
129	  // Box: períodos (header preto)
130	  doc.setFillColor(60, 60, 60);
131	  doc.rect(margin, y, w - margin * 2, 8, 'F');
132	  doc.setTextColor(255, 255, 255);
133	  doc.setFont('helvetica', 'bold');
134	  doc.text('PERÍODOS', w / 2, y + 6, { align: 'center' });
135	  doc.setTextColor(0, 0, 0);
136	  y += 8;
137	
138	  doc.rect(margin, y, w - margin * 2, 22);
139	  doc.setFontSize(10);
140	  doc.setFont('helvetica', 'bold');
141	  doc.text('Período aquisitivo', margin + 3, y + 7);
142	  doc.setFont('helvetica', 'normal');
143	  doc.text(
144	    `${formatDate(input.periodo_aquisitivo_inicio)} a ${formatDate(input.periodo_aquisitivo_fim)}`,
145	    margin + 60,
146	    y + 7,
147	  );
148	
149	  doc.setFont('helvetica', 'bold');
150	  doc.text('Período Gozo das Férias', margin + 3, y + 14);
151	  doc.setFont('helvetica', 'normal');
152	  doc.text(
153	    `${formatDate(input.data_inicio_gozo)} a ${formatDate(input.data_fim_gozo)}`,
154	    margin + 60,
155	    y + 14,
156	  );
157	
158	  doc.setFont('helvetica', 'bold');
159	  doc.text('Data pedido Abono Pecuniário', margin + 3, y + 21);
160	  doc.setFont('helvetica', 'normal');
161	  doc.text('—', margin + 60, y + 21);
162	
163	  y += 26;
164	
165	  // Box: texto legal
166	  doc.rect(margin, y, w - margin * 2, 35);
167	  doc.setFontSize(10);
168	  const textoLegal =
169	    'Pelo presente, comunicamos-lhe que, de acordo com a lei, ser-lhe-ão concedidas férias relativas ao período acima descrito e a sua disposição ficará o valor a ser pago adiantadamente.';
170	  const lines = doc.splitTextToSize(textoLegal, w - margin * 2 - 6);
171	  doc.text(lines, margin + 3, y + 6);
172	
173	  const cidade = input.cidade ?? 'Brasília';
174	  const dataEm = input.data_emissao ?? new Date().toISOString();
175	  doc.setFont('helvetica', 'bold');
176	  doc.text(`${cidade}, ${dataExtenso(dataEm)}`, w / 2, y + 30, { align: 'center' });
177	
178	  y += 42;
179	
180	  // Assinaturas
181	  doc.line(margin + 20, y + 12, w - margin - 20, y + 12);
182	  doc.setFontSize(10);
183	  doc.setFont('helvetica', 'normal');
184	  doc.text(input.empresa, w / 2, y + 18, { align: 'center' });
185	
186	  y += 28;
187	  doc.line(margin + 20, y + 12, w - margin - 20, y + 12);
188	  doc.text(input.empregado, w / 2, y + 18, { align: 'center' });
189	
190	  return doc;
191	}
192	
193	// =============================================================================
194	// ADVERTÊNCIA DISCIPLINAR
195	// =============================================================================
196	export interface AdvertenciaInput {
197	  empresa: string;
198	  cnpj?: string | null;
199	  empregado: string;
200	  cpf: string;
201	  cargo: string;
202	  data_ocorrencia: string;
203	  data_aplicacao?: string;
204	  descricao_ocorrencia: string;
205	  tipo:
206	    | 'advertencia_verbal'
207	    | 'advertencia_escrita'
208	    | 'suspensao_1'
209	    | 'suspensao_2'
210	    | 'suspensao_3'
211	    | 'suspensao_5';
212	  dias_suspensao?: number | null;
213	  data_inicio_cumprimento?: string | null;
214	  data_retorno_trabalho?: string | null;
215	  observacoes?: string | null;
216	}
217	
218	const TIPO_PUNITIVO_TITULOS: Record<AdvertenciaInput['tipo'], string> = {
219	  advertencia_verbal: 'ADVERTÊNCIA VERBAL',
220	  advertencia_escrita: 'ADVERTÊNCIA DISCIPLINAR',
221	  suspensao_1: 'SUSPENSÃO DISCIPLINAR · 1 DIA',
222	  suspensao_2: 'SUSPENSÃO DISCIPLINAR · 2 DIAS',
223	  suspensao_3: 'SUSPENSÃO DISCIPLINAR · 3 DIAS',
224	  suspensao_5: 'SUSPENSÃO DISCIPLINAR · 5 DIAS',
225	};
226	
227	export function gerarAdvertenciaPdf(input: AdvertenciaInput): jsPDF {
228	  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
229	  const w = doc.internal.pageSize.getWidth();
230	  const margin = 18;
231	  let y = 22;
232	
233	  // Título
234	  doc.setFont('helvetica', 'bold');
235	  doc.setFontSize(14);
236	  doc.text(TIPO_PUNITIVO_TITULOS[input.tipo], w / 2, y, { align: 'center' });
237	  y += 14;
238	
239	  // Dados
240	  const printRow = (label: string, value: string | null | undefined) => {
241	    doc.setFont('helvetica', 'bold');
242	    doc.setFontSize(10);
243	    doc.text(`${label}:`, margin, y);
244	    doc.setFont('helvetica', 'normal');
245	    doc.text(value ?? '—', margin + 50, y);
246	    y += 6;
247	  };
248	
249	  printRow('Empresa', input.empresa);
250	  if (input.cnpj) printRow('CNPJ', formatCnpj(input.cnpj));
251	  printRow('Funcionário(a)', input.empregado);
252	  printRow('CPF', formatCpf(input.cpf));
253	  printRow('Cargo', input.cargo);
254	  printRow('Data da ocorrência', formatDate(input.data_ocorrencia));
255	  printRow(
256	    'Data da advertência',
257	    input.data_aplicacao ? formatDate(input.data_aplicacao) : formatDate(new Date().toISOString()),
258	  );
259	
260	  if (input.tipo.startsWith('suspensao_')) {
261	    printRow('Dias de suspensão', String(input.dias_suspensao ?? '—'));
262	    if (input.data_inicio_cumprimento)
263	      printRow('Início do cumprimento', formatDate(input.data_inicio_cumprimento));
264	    if (input.data_retorno_trabalho)
265	      printRow('Retorno ao trabalho', formatDate(input.data_retorno_trabalho));
266	  }
267	
268	  y += 4;
269	  doc.setFont('helvetica', 'bold');
270	  doc.text('Descrição da ocorrência:', margin, y);
271	  y += 6;
272	  doc.setFont('helvetica', 'normal');
273	  const descLines = doc.splitTextToSize(input.descricao_ocorrencia, w - margin * 2);
274	  doc.text(descLines, margin, y);
275	  y += descLines.length * 5 + 4;
276	
277	  doc.setFont('helvetica', 'bold');
278	  doc.text('Medida disciplinar:', margin, y);
279	  y += 6;
280	  doc.setFont('helvetica', 'normal');
281	  const medida = (() => {
282	    switch (input.tipo) {
283	      case 'advertencia_verbal':
284	      case 'advertencia_escrita':
285	        return 'Diante do ocorrido, o(a) colaborador(a) está sendo advertido(a) formalmente, ficando ciente de que a reincidência poderá acarretar medidas mais severas.';
286	      default:
287	        return `Diante do ocorrido, o(a) colaborador(a) está recebendo SUSPENSÃO DE ${
288	          input.dias_suspensao ?? 0
289	        } DIA${
290	          (input.dias_suspensao ?? 0) === 1 ? '' : 'S'
291	        }, com cumprimento conforme datas indicadas. Reincidência poderá acarretar rescisão por justa causa.`;
292	    }
293	  })();
294	  const medidaLines = doc.splitTextToSize(medida, w - margin * 2);
295	  doc.text(medidaLines, margin, y);
296	  y += medidaLines.length * 5 + 6;
297	
298	  doc.setFont('helvetica', 'bold');
299	  doc.text('Observações:', margin, y);
300	  y += 6;
301	  if (input.observacoes) {
302	    doc.setFont('helvetica', 'normal');
303	    const obsLines = doc.splitTextToSize(input.observacoes, w - margin * 2);
304	    doc.text(obsLines, margin, y);
305	    y += obsLines.length * 5 + 4;
306	  } else {
307	    doc.line(margin, y + 1, w - margin, y + 1);
308	    y += 6;
309	    doc.line(margin, y + 1, w - margin, y + 1);
310	    y += 8;
311	  }
312	
313	  doc.setFont('helvetica', 'normal');
314	  doc.text('Declaro que estou ciente do conteúdo desta advertência.', margin, y);
315	  y += 18;
316	
317	  doc.line(margin, y, margin + 80, y);
318	  doc.setFont('helvetica', 'bold');
319	  doc.setFontSize(9);
320	  doc.text('Assinatura do(a) colaborador(a)', margin, y + 5);
321	
322	  y += 16;
323	  doc.line(margin, y, margin + 80, y);
324	  doc.text('Assinatura do responsável', margin, y + 5);
325	
326	  // Testemunhas (CLT — duas testemunhas para validar a aplicação disciplinar)
327	  y += 18;
328	  if (y > 255) {
329	    doc.addPage();
330	    y = 30;
331	  }
332	  doc.setFont('helvetica', 'bold');
333	  doc.setFontSize(9);
334	  doc.text('Testemunhas:', margin, y);
335	  y += 10;
336	  doc.setLineWidth(0.3);
337	  const colW = (w - margin * 2 - 10) / 2;
338	  doc.line(margin, y, margin + colW, y);
339	  doc.line(w - margin - colW, y, w - margin, y);
340	  doc.setFont('helvetica', 'normal');
341	  doc.setFontSize(8);
342	  doc.text('Testemunha 1 — Nome / CPF', margin, y + 4);
343	  doc.text('Testemunha 2 — Nome / CPF', w - margin - colW, y + 4);
344	
345	  y += 14;
346	  doc.setFontSize(9);
347	  doc.setFont('helvetica', 'normal');
348	  doc.text('Data: ____ / ____ / __________', margin, y);
349	
350	  return doc;
351	}
352	
353	// =============================================================================
354	// TRCT — Termo de Rescisão de Contrato de Trabalho
355	// =============================================================================
356	export interface TRCTPdfInput {
357	  empresa: string;
358	  cnpj?: string | null;
359	  empregado: string;
360	  cpf: string;
361	  cargo: string;
362	  data_admissao: string;
363	  data_demissao: string;
364	  tipo_desligamento_label: string;
365	  motivo: string;
366	  saldoSalario: number;
367	  avisoPrevio: number;
368	  feriasVencidas: number;
369	  feriasProporcionais: number;
370	  decimoTerceiroProporcional: number;
371	  multaFGTS: number;
372	  total: number;
373	  observacoes: string[];
374	}
375	
376	function brl(n: number): string {
377	  return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
378	}
379	
380	export function gerarTRCTPdf(input: TRCTPdfInput): jsPDF {
381	  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
382	  const w = doc.internal.pageSize.getWidth();
383	  const margin = 18;
384	  let y = 20;
385	
386	  doc.setFont('helvetica', 'bold');
387	  doc.setFontSize(14);
388	  doc.text('TERMO DE RESCISÃO DE CONTRATO DE TRABALHO', w / 2, y, { align: 'center' });
389	  y += 5;
390	  doc.setFont('helvetica', 'normal');
391	  doc.setFontSize(9);
392	  doc.text('Estimativa — sujeita a conferência da contabilidade', w / 2, y, { align: 'center' });
393	  y += 10;
394	
395	  const row = (label: string, value: string | null | undefined) => {
396	    doc.setFont('helvetica', 'bold');
397	    doc.setFontSize(10);
398	    doc.text(`${label}:`, margin, y);
399	    doc.setFont('helvetica', 'normal');
400	    doc.text(value ?? '—', margin + 50, y);
401	    y += 6;
402	  };
403	
404	  row('Empresa', input.empresa);
405	  if (input.cnpj) row('CNPJ', formatCnpj(input.cnpj));
406	  row('Empregado', input.empregado);
407	  row('CPF', formatCpf(input.cpf));
408	  row('Cargo', input.cargo);
409	  row('Admissão', formatDate(input.data_admissao));
410	  row('Demissão', formatDate(input.data_demissao));
411	  row('Tipo de rescisão', input.tipo_desligamento_label);
412	  y += 2;
413	  doc.setFont('helvetica', 'bold');
414	  doc.text('Motivo:', margin, y);
415	  y += 5;
416	  doc.setFont('helvetica', 'normal');
417	  const motivoLines = doc.splitTextToSize(input.motivo, w - margin * 2);
418	  doc.text(motivoLines, margin, y);
419	  y += motivoLines.length * 5 + 6;
420	
421	  // Bloco de verbas
422	  doc.setFillColor(60, 60, 60);
423	  doc.rect(margin, y, w - margin * 2, 8, 'F');
424	  doc.setTextColor(255, 255, 255);
425	  doc.setFont('helvetica', 'bold');
426	  doc.text('VERBAS RESCISÓRIAS', w / 2, y + 6, { align: 'center' });
427	  doc.setTextColor(0, 0, 0);
428	  y += 10;
429	
430	  const verba = (label: string, valor: number) => {
431	    if (valor === 0) return;
432	    doc.setFont('helvetica', 'normal');
433	    doc.text(label, margin, y);
434	    doc.text(brl(valor), w - margin, y, { align: 'right' });
435	    y += 6;
436	  };
437	
438	  verba('Saldo de salário', input.saldoSalario);
439	  verba('Aviso prévio indenizado', input.avisoPrevio);
440	  verba('Férias vencidas + 1/3', input.feriasVencidas);
441	  verba('Férias proporcionais + 1/3', input.feriasProporcionais);
442	  verba('13º proporcional', input.decimoTerceiroProporcional);
443	  verba('Multa FGTS', input.multaFGTS);
444	
445	  y += 2;
446	  doc.setLineWidth(0.5);
447	  doc.line(margin, y, w - margin, y);
448	  y += 5;
449	  doc.setFont('helvetica', 'bold');
450	  doc.setFontSize(11);
451	  doc.text('TOTAL ESTIMADO', margin, y);
452	  doc.text(brl(input.total), w - margin, y, { align: 'right' });
453	  y += 10;
454	
455	  if (input.observacoes.length > 0) {
456	    doc.setFont('helvetica', 'bold');
457	    doc.setFontSize(10);
458	    doc.text('Observações:', margin, y);
459	    y += 5;
460	    doc.setFont('helvetica', 'normal');
461	    doc.setFontSize(9);
462	    input.observacoes.forEach((o) => {
463	      const lines = doc.splitTextToSize(`• ${o}`, w - margin * 2);
464	      doc.text(lines, margin, y);
465	      y += lines.length * 4 + 1;
466	    });
467	    y += 4;
468	  }
469	
470	  // Assinaturas
471	  if (y > 240) {
472	    doc.addPage();
473	    y = 30;
474	  }
475	  y += 10;
476	  doc.line(margin, y, margin + 80, y);
477	  doc.setFontSize(9);
478	  doc.setFont('helvetica', 'bold');
479	  doc.text('Empregado', margin, y + 5);
480	  doc.setFont('helvetica', 'normal');
481	  doc.text(input.empregado, margin, y + 9);
482	
483	  doc.line(w - margin - 80, y, w - margin, y);
484	  doc.setFont('helvetica', 'bold');
485	  doc.text('Empresa', w - margin - 80, y + 5);
486	  doc.setFont('helvetica', 'normal');
487	  doc.text(input.empresa, w - margin - 80, y + 9);
488	
489	  return doc;
490	}
491	
492	// =============================================================================
493	// CONTRATO DE ADMISSÃO (modelo CLT padrão)
494	// =============================================================================
495	export interface ContratoAdmissaoInput {
496	  empresa: string;
497	  cnpj: string;
498	  endereco_empresa?: string;
499	  empregado: string;
500	  cpf: string;
501	  rg?: string | null;
502	  endereco_empregado?: string | null;
503	  data_nascimento: string;
504	  cargo: string;
505	  salario_base: number | null;
506	  data_admissao: string;
507	  jornada_trabalho?: string | null;
508	  contrato_tipo: 'experiencia' | 'indeterminado' | 'determinado';
509	  data_fim_experiencia?: string | null;
510	  clausula_assecuratoria?: boolean;
511	  cidade?: string;
512	}
513	
514	export function gerarContratoAdmissaoPdf(input: ContratoAdmissaoInput): jsPDF {
515	  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
516	  const w = doc.internal.pageSize.getWidth();
517	  const margin = 20;
518	  let y = 22;
519	
520	  doc.setFont('helvetica', 'bold');
521	  doc.setFontSize(14);
522	  doc.text('CONTRATO INDIVIDUAL DE TRABALHO', w / 2, y, { align: 'center' });
523	  y += 6;
524	  doc.setFontSize(11);
525	  const subtit =
526	    input.contrato_tipo === 'experiencia'
527	      ? 'EM REGIME DE EXPERIÊNCIA (CLT, art. 443, §2º, alínea c)'
528	      : input.contrato_tipo === 'determinado'
529	      ? 'POR PRAZO DETERMINADO (CLT, art. 443)'
530	      : 'POR PRAZO INDETERMINADO';
531	  doc.text(subtit, w / 2, y, { align: 'center' });
532	  y += 12;
533	
534	  doc.setFontSize(10);
535	  doc.setFont('helvetica', 'bold');
536	  doc.text('EMPREGADOR:', margin, y);
