6	/**
7	 * Gerador de Relatório PDF de Produção Diária.
8	 *
9	 * Relatório de alto nível: totais por produto, consolidado de TODAS as lojas.
10	 * Segue o padrão visual world-class do Cofre/DRE: border Momma green dupla,
11	 * logo header, watermark central, header/footer por página com paginação,
12	 * resumo executivo e tabela analítica paginada.
13	 *
14	 * O helper `aggregateProducao` é PURO (sem jsPDF) e testável isoladamente.
15	 */
16	
17	// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────
18	
19	export interface ProducaoEntry {
20	  date: string;
21	  product_name: string;
22	  quantity: number;
23	}
24	
25	export interface ProducaoAggregate {
26	  totalQuantity: number;
27	  /** Nº de produtos distintos (por nome). */
28	  distinctProducts: number;
29	  /** Nº de datas distintas com produção. */
30	  activeDays: number;
31	  /** totalQuantity / activeDays (0 se activeDays = 0). */
32	  avgPerDay: number;
33	  /** Ordenado por quantity desc, depois nome asc. */
34	  byProduct: Array<{ product_name: string; quantity: number }>;
35	}
36	
37	export interface GenerateProducaoDiariaPdfParams {
38	  entries: ProducaoEntry[];
39	  dateStart: string; // yyyy-MM-dd
40	  dateEnd: string; // yyyy-MM-dd
41	}
42	
43	// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────
44	
45	/**
46	 * Agrega lançamentos de produção em totais de alto nível.
47	 *
48	 * - Produtos com mesmo nome têm suas quantidades somadas.
49	 * - Dias são contados por datas distintas (mesma data conta 1).
50	 * - Lista vazia retorna tudo zerado e arrays vazios.
51	 */
52	export function aggregateProducao(entries: ProducaoEntry[]): ProducaoAggregate {
53	  const productTotals = new Map<string, number>();
54	  const distinctDates = new Set<string>();
55	  let totalQuantity = 0;
56	
57	  for (const entry of entries) {
58	    const quantity = Number(entry.quantity) || 0;
59	    totalQuantity += quantity;
60	
61	    const productKey = entry.product_name;
62	    productTotals.set(productKey, (productTotals.get(productKey) ?? 0) + quantity);
63	
64	    if (entry.date) {
65	      distinctDates.add(entry.date);
66	    }
67	  }
68	
69	  const activeDays = distinctDates.size;
70	
71	  const byProduct = Array.from(productTotals.entries())
72	    .map(([product_name, quantity]) => ({ product_name, quantity }))
73	    .sort((a, b) => {
74	      if (b.quantity !== a.quantity) return b.quantity - a.quantity;
75	      return a.product_name.localeCompare(b.product_name, 'pt-BR');
76	    });
77	
78	  return {
79	    totalQuantity,
80	    distinctProducts: productTotals.size,
81	    activeDays,
82	    avgPerDay: activeDays === 0 ? 0 : totalQuantity / activeDays,
83	    byProduct,
84	  };
85	}
