1	/**
2	 * Lógica pura extraída do FinanceReportsModal.tsx para testes unitários.
3	 * Cálculos de totais, agrupamentos por mês/categoria/responsável/pagamento.
4	 */
5	import { format } from "date-fns";
6	import { roundMoney } from '@/shared/lib/roundMoney';
7	
8	export interface MovementRow {
9	  id: number;
10	  tipo_operacao: "entrada" | "saida";
11	  valor: number;
12	  descricao: string;
13	  categoria: string;
14	  forma_pagamento: string | null;
15	  observacoes: string | null;
16	  responsavel_nome: string;
17	  data_operacao: string; // ISO
18	  user_id: string | null;
19	  loja_id: number | null;
20	}
21	
22	export interface FinanceTotals {
23	  entradas: number;
24	  saidas: number;
25	  saldo: number;
26	  count: number;
27	}
28	
29	export interface MonthlyData {
30	  mes: string;
31	  receitas: number;
32	  despesas: number;
33	  saldo: number;
34	}
35	
36	export interface CategoriaData {
37	  name: string;
38	  value: number;
39	}
40	
41	export interface ResponsavelData {
42	  nome: string;
43	  total: number;
44	  count: number;
45	}
46	
47	export interface PagamentoData {
48	  name: string;
49	  value: number;
50	}
51	
52	/**
53	 * Verifica se o nome da loja contém "fábrica" (normalizado, sem acento).
54	 */
55	export function isFactoryName(name?: string): boolean {
56	  return (name || "")
57	    .normalize("NFD")
58	    .replace(/[\u0300-\u036f]/g, "")
59	    .toLowerCase()
60	    .includes("fabrica");
61	}
62	
63	/**
64	 * Calcula totais de entradas, saídas e saldo.
65	 */
66	export function calculateTotals(rows: MovementRow[]): FinanceTotals {
67	  const entradas = roundMoney(rows
68	    .filter((r) => r.tipo_operacao === "entrada")
69	    .reduce((s, r) => s + Number(r.valor || 0), 0));
70	  const saidas = roundMoney(rows
71	    .filter((r) => r.tipo_operacao === "saida")
72	    .reduce((s, r) => s + Number(r.valor || 0), 0));
73	  return { entradas, saidas, saldo: roundMoney(entradas - saidas), count: rows.length };
74	}
75	
76	/**
77	 * Agrupa movimentações por mês (yyyy-MM), calculando receitas, despesas e saldo.
78	 */
79	export function groupByMonth(rows: MovementRow[]): MonthlyData[] {
80	  const map: Record<string, MonthlyData> = {};
81	  rows.forEach((r) => {
82	    const mes = format(new Date(r.data_operacao), "yyyy-MM");
83	    if (!map[mes]) map[mes] = { mes, receitas: 0, despesas: 0, saldo: 0 };
84	    if (r.tipo_operacao === "entrada") map[mes].receitas = roundMoney(map[mes].receitas + Number(r.valor || 0));
85	    else map[mes].despesas = roundMoney(map[mes].despesas + Number(r.valor || 0));
86	    map[mes].saldo = roundMoney(map[mes].receitas - map[mes].despesas);
87	  });
88	  return Object.values(map).sort((a, b) => a.mes.localeCompare(b.mes));
89	}
90	
91	/**
92	 * Agrupa movimentações por categoria, somando valores absolutos.
93	 */
94	export function groupByCategoria(rows: MovementRow[]): CategoriaData[] {
95	  const map: Record<string, number> = {};
96	  rows.forEach((r) => {
97	    const k = r.categoria || "Sem categoria";
98	    map[k] = roundMoney((map[k] || 0) + Number(r.valor || 0));
99	  });
100	  return Object.entries(map)
101	    .map(([name, value]) => ({ name, value }))
102	    .sort((a, b) => b.value - a.value);
103	}
104	
105	/**
106	 * Agrupa movimentações por responsável (top 10 por total).
107	 */
108	export function groupByResponsavel(rows: MovementRow[]): ResponsavelData[] {
109	  const map: Record<string, ResponsavelData> = {};
110	  rows.forEach((r) => {
111	    const k = r.responsavel_nome || "Desconhecido";
112	    if (!map[k]) map[k] = { nome: k, total: 0, count: 0 };
113	    map[k].total = roundMoney(map[k].total + Number(r.valor || 0));
114	    map[k].count += 1;
115	  });
116	  return Object.values(map)
117	    .sort((a, b) => b.total - a.total)
118	    .slice(0, 10);
119	}
120	
121	/**
122	 * Agrupa movimentações por forma de pagamento.
123	 */
124	export function groupByPagamento(rows: MovementRow[]): PagamentoData[] {
125	  const map: Record<string, number> = {};
126	  rows.forEach((r) => {
127	    const k = r.forma_pagamento || "N/D";
128	    map[k] = roundMoney((map[k] || 0) + Number(r.valor || 0));
129	  });
130	  return Object.entries(map).map(([name, value]) => ({ name, value }));
131	}
